// T3 "Downpour": a street market under two overpasses on the City Night avenue, in a storm.
// GPU compute stress: Niagara GPU sims (rain streaks with depth-buffer collision, ground splashes,
// failing-sign sparks, vent steam, dense lit smoke, a mesh drone swarm) plus heavy translucent overdraw.
// Systems are generated by the OmaFx editor commandlet (Source/OmaBenchEditor); every one is
// deterministic (fixed seed, fixed 1/90 s sim tick, fixed warmup). Meshes come from art/blender/market.py.
#include "BenchGameMode.h"
#include "BenchCommon.h"
#include "Components/StaticMeshComponent.h"
#include "Components/PointLightComponent.h"
#include "Components/SpotLightComponent.h"
#include "Components/InstancedStaticMeshComponent.h"
#include "Engine/StaticMesh.h"
#include "Engine/World.h"
#include "Materials/MaterialInstanceDynamic.h"
#include "Camera/CameraActor.h"
#include "GameFramework/PlayerController.h"
#include "NiagaraComponent.h"
#include "NiagaraSystem.h"

DEFINE_LOG_CATEGORY_STATIC(LogOmaRain, Log, All);

namespace
{
	UNiagaraSystem* LoadFx(const TCHAR* Name)
	{
		UNiagaraSystem* S = LoadObject<UNiagaraSystem>(nullptr, *FString::Printf(TEXT("/Game/OmaBench/Fx/%s.%s"), Name, Name));
		if (!S) UE_LOG(LogOmaRain, Error, TEXT("Missing Niagara system %s (run art/build.sh)"), Name);
		return S;
	}
}

void ABenchGameMode::BuildDownpour()
{
	UWorld* W = GetWorld();
	FRandomStream Rng(9091);
	FActorSpawnParameters P; P.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
	const FLinearColor Cyan = Pal(TEXT("bright_cyan"), FLinearColor(0, 0.9f, 1)), Mag = Pal(TEXT("bright_magenta"), FLinearColor(1, 0.1f, 0.6f));
	const FLinearColor Amber = Pal(TEXT("bright_yellow"), FLinearColor(1, 0.7f, 0.1f)), Accent = Pal(TEXT("accent"), FLinearColor(0.5f, 0.5f, 0.9f));
	const FLinearColor Neon[] = { Cyan, Mag, Amber, Pal(TEXT("bright_green"), FLinearColor(0.2f, 1, 0.4f)), Accent };
	const FLinearColor Warm(1, 0.85f, 0.6f);

	AActor* Site = W->SpawnActor<AActor>(AActor::StaticClass(), FTransform::Identity, P);
	USceneComponent* Root = NewObject<USceneComponent>(Site, TEXT("MarketRoot")); Root->SetMobility(EComponentMobility::Static);
	Site->SetRootComponent(Root); Root->RegisterComponent();
	auto MID = [&](UMaterialInterface* Base, TFunctionRef<void(UMaterialInstanceDynamic*)> F) { UMaterialInstanceDynamic* M = UMaterialInstanceDynamic::Create(Base ? Base : BaseMaterial.Get(), Site); F(M); return M; };
	auto ChromeV = [&](FLinearColor B, float R, float Mt) { return MID(ChromeMaterial, [&](UMaterialInstanceDynamic* M){ M->SetVectorParameterValue(TEXT("Base"), B); M->SetScalarParameterValue(TEXT("Roughness"), R); M->SetScalarParameterValue(TEXT("Metallic"), Mt); }); };
	auto Emit = [&](FLinearColor C, float I) { return MID(EmitMaterial, [&](UMaterialInstanceDynamic* M){ M->SetVectorParameterValue(TEXT("Color"), C * I); }); };
	UMaterialInterface* Dark = ChromeV(FLinearColor(0.03f, 0.03f, 0.035f), 0.35f, 0.2f);
	UMaterialInterface* Concrete = OmaBench::LoadCC0(TEXT("MIW_Concrete034"), ChromeV(FLinearColor(0.08f, 0.08f, 0.085f), 0.6f, 0.0f));
	TMap<FName, UMaterialInterface*> Common = { {TEXT("Chrome"), ChromeV(FLinearColor(0.7f, 0.72f, 0.75f), 0.15f, 1)}, {TEXT("Dark"), Dark},
		{TEXT("Paint"), ChromeV(FLinearColor(0.1f, 0.1f, 0.11f), 0.4f, 0.3f)}, {TEXT("EmitWhite"), Emit(FLinearColor(0.9f, 0.95f, 1), 14)},
		{TEXT("EmitAmber"), Emit(Amber, 18)}, {TEXT("EmitGlyph"), Emit(Cyan, 20)}, {TEXT("EmitRed"), Emit(FLinearColor(1, 0.05f, 0.03f), 20)},
		{TEXT("EmitBlue"), Emit(FLinearColor(0.1f, 0.4f, 1), 20)} };

	int32 NC = 0;
	auto Place = [&](UStaticMesh* Mesh, const FVector& Loc, float Yaw, const TMap<FName, UMaterialInterface*>& Slots, float Scale = 1.f) {
		if (!Mesh) return (UStaticMeshComponent*)nullptr;
		UStaticMeshComponent* C = NewObject<UStaticMeshComponent>(Site, *FString::Printf(TEXT("M%d"), NC++));
		C->SetStaticMesh(Mesh); C->SetMobility(EComponentMobility::Static); C->SetCollisionEnabled(ECollisionEnabled::NoCollision);
		C->SetRelativeTransform(FTransform(FRotator(0, Yaw, 0), Loc, FVector(Scale))); C->SetupAttachment(Root);
		OmaBench::BindSlots(C, Slots); C->RegisterComponent(); return C; };
	auto Box = [&](UMaterialInterface* M, const FVector& Loc, const FVector& Size) { TMap<FName, UMaterialInterface*> S; UStaticMeshComponent* C = Place(CubeMesh, Loc, 0, S); if (C) { C->SetRelativeScale3D(Size / 100.f); C->SetMaterial(0, M); } return C; };
	auto Light = [&](const FVector& Loc, FLinearColor Col, float I, float R) {
		UPointLightComponent* L = NewObject<UPointLightComponent>(Site, *FString::Printf(TEXT("L%d"), NC++));
		L->SetupAttachment(Root); L->SetMobility(EComponentMobility::Movable); L->RegisterComponent(); L->SetWorldLocation(Loc);
		L->SetLightColor(Col); L->SetIntensity(I); L->SetAttenuationRadius(R); L->SetCastShadows(false); return L; };
	auto Fx = [&](const TCHAR* Name, AActor* Owner, const FVector& Loc, int32 SeedOffset) {
		UNiagaraSystem* S = LoadFx(Name); if (!S) return (UNiagaraComponent*)nullptr;
		UNiagaraComponent* C = NewObject<UNiagaraComponent>(Owner, *FString::Printf(TEXT("Fx%d"), NC++));
		C->SetAsset(S); C->SetAutoActivate(false); C->SetRandomSeedOffset(SeedOffset);
		C->SetupAttachment(Owner->GetRootComponent()); C->RegisterComponent(); C->SetWorldLocation(Loc);
		DownpourFx.Add(C); return C; };

	// Overpasses: two elevated spans crossing the avenue (deck ~9 m up) on concrete pillars.
	UStaticMesh* Over = OmaBench::LoadMesh(TEXT("SM_Overpass"));
	for (float Y : { 2500.f, 5600.f })
	{
		Place(Over, FVector(0, Y, 950), 0, Common, 1.f);
		for (int32 s = -1; s <= 1; s += 2) for (int32 r = -1; r <= 1; r += 2) Box(Concrete, FVector(s * 1350, Y + r * 220, 430), FVector(110, 110, 860));
	}
	// Market stalls along both kerbs, facing the street; hanging amber lamps light the awnings.
	UStaticMesh* Stalls[3] = { OmaBench::LoadMesh(TEXT("SM_Stall3")), OmaBench::LoadMesh(TEXT("SM_Stall8")), OmaBench::LoadMesh(TEXT("SM_Stall15")) };
	int32 NStall = 0;
	for (int32 s = -1; s <= 1; s += 2)
		for (float y = 700; y < 8400; y += Rng.FRandRange(380, 520))
		{
			if (FMath::Abs(y - 6000) < 300) continue;  // cross street at GY=6
			TMap<FName, UMaterialInterface*> S = Common; S.Add(TEXT("EmitGlyph"), Emit(Neon[Rng.RandRange(0, 4)], 18));
			S.Add(TEXT("Paint"), ChromeV(Neon[Rng.RandRange(0, 4)] * 0.25f, 0.5f, 0.0f));
			Place(Stalls[Rng.RandRange(0, 2)], FVector(s * 1180, y, 0), s < 0 ? -90.f : 90.f, S);
			if ((NStall++ % 2) == 0) Light(FVector(s * 1160, y, 210), Warm, 9000, 900);
		}
	// Steam vents in the roadway; each gets its own GPU steam plume (seed offset per vent).
	UStaticMesh* Vent = OmaBench::LoadMesh(TEXT("SM_Vent"));
	for (int32 i = 0; i < 10; ++i)
	{
		const FVector L(Rng.FRandRange(-700, 700), 900 + i * 760 + Rng.FRandRange(-150, 150), 0);
		Place(Vent, L, Rng.FRandRange(0, 90), Common);
		Fx(TEXT("NS_Steam"), Site, L + FVector(0, 0, 12), 17 * i + 1);
	}
	// Rune signs (invented glyphs, no words) on the facades either side; one failing sign sputters sparks.
	UStaticMesh* SignV[2] = { OmaBench::LoadMesh(TEXT("SM_SignV1")), OmaBench::LoadMesh(TEXT("SM_SignV2")) };
	for (int32 i = 0; i < 8; ++i)
	{
		const int32 s = (i % 2) ? 1 : -1; const FLinearColor C = Neon[i % 5];
		const FVector L(s * 1480, 1100 + i * 950, 420 + (i % 3) * 180);
		TMap<FName, UMaterialInterface*> S = Common; S.Add(TEXT("EmitGlyph"), Emit(C, 24));
		if (i == 4) { FailSign = UMaterialInstanceDynamic::Create(EmitMaterial ? EmitMaterial.Get() : BaseMaterial.Get(), Site); FailColor = C * 24; S.Add(TEXT("EmitGlyph"), FailSign); }
		Place(SignV[i % 2], L, s < 0 ? -90.f : 90.f, S, 1.1f);
		UPointLightComponent* PL = Light(L + FVector(-s * 350, 0, 200), C, 60000, 2200);
		if (i == 4) { FailLight = PL; FailBase = 60000; SparkPos = L + FVector(-s * 120, 0, 120); }
	}
	Place(OmaBench::LoadMesh(TEXT("SM_SignH1")), FVector(0, 2500 - 380, 820), 0, Common, 1.2f);  // hangs off the overpass facing the camera
	Fx(TEXT("NS_Sparks"), Site, SparkPos, 3);

	// Big systems: smoke fills the market, drones swarm overhead; rain + splashes follow the camera.
	Fx(TEXT("NS_Smoke"), Site, FVector(0, 3000, 0), 5);
	// Patrol drones: a few scripted actors (no physics, no particles) flying smooth deterministic
	// formation loops with banking, sweeping searchlight cones and blinking nav lights.
	{
		UStaticMesh* DM = OmaBench::LoadMesh(TEXT("SM_Drone"));
		TMap<FName, UMaterialInterface*> DS = Common; DS.Add(TEXT("EmitBlue"), Emit(Cyan, 30));
		for (int32 i = 0; i < 6 && DM; ++i)
		{
			AActor* D = W->SpawnActor<AActor>(AActor::StaticClass(), FTransform::Identity, P);
			UStaticMeshComponent* MC = NewObject<UStaticMeshComponent>(D, TEXT("Body")); MC->SetStaticMesh(DM); MC->SetMobility(EComponentMobility::Movable);
			MC->SetCollisionEnabled(ECollisionEnabled::NoCollision); MC->SetRelativeScale3D(FVector(2.5f)); D->SetRootComponent(MC); OmaBench::BindSlots(MC, DS); MC->RegisterComponent();
			USpotLightComponent* S = NewObject<USpotLightComponent>(D, TEXT("Search")); S->SetupAttachment(MC); S->SetMobility(EComponentMobility::Movable); S->RegisterComponent();
			S->SetLightColor(FLinearColor(0.85f, 0.92f, 1)); S->SetIntensity(400000); S->SetAttenuationRadius(5000); S->SetOuterConeAngle(14); S->SetInnerConeAngle(6);
			S->SetCastShadows(false); S->SetVolumetricScatteringIntensity(Cfg().SearchScatter);   // visible cone through fog/rain
			UPointLightComponent* Nav[2];
			for (int32 k = 0; k < 2; ++k)
			{
				Nav[k] = NewObject<UPointLightComponent>(D, *FString::Printf(TEXT("Nav%d"), k)); Nav[k]->SetupAttachment(MC); Nav[k]->SetMobility(EComponentMobility::Movable); Nav[k]->RegisterComponent();
				Nav[k]->SetRelativeLocation(FVector(0, k ? 14.f : -14.f, 2)); Nav[k]->SetLightColor(k ? FLinearColor(0.1f, 1, 0.2f) : FLinearColor(1, 0.05f, 0.03f));
				Nav[k]->SetAttenuationRadius(500); Nav[k]->SetCastShadows(false);
			}
			Drones.Add({ D, S, Nav[0], Nav[1], i });
		}
	}
	RainHost = W->SpawnActor<AActor>(AActor::StaticClass(), FTransform::Identity, P);
	USceneComponent* RR = NewObject<USceneComponent>(RainHost, TEXT("RainRoot")); RR->SetMobility(EComponentMobility::Movable);
	RainHost->SetRootComponent(RR); RR->RegisterComponent();
	Fx(TEXT("NS_Rain"), RainHost, FVector::ZeroVector, 1);
	Fx(TEXT("NS_Splash"), RainHost, FVector::ZeroVector, 2);
	// Tier particle budgets (user parameters exposed by the OmaFx systems).
	for (UNiagaraComponent* C : DownpourFx) if (C)
	{
		C->SetVariableFloat(TEXT("RainRate"), Cfg().Rain); C->SetVariableFloat(TEXT("SplashRate"), Cfg().Splash);
		C->SetVariableFloat(TEXT("SteamRate"), Cfg().Steam); C->SetVariableFloat(TEXT("SmokeRate"), Cfg().Smoke);
	}
	UE_LOG(LogOmaRain, Display, TEXT("Downpour built: %d stalls, %d fx components"), NStall, DownpourFx.Num());
}

void ABenchGameMode::SetDownpourActive(bool bOn)
{
	for (UNiagaraComponent* C : DownpourFx) if (C) { if (bOn) C->Activate(true); else C->DeactivateImmediate(); }
	if (Camera) for (UActorComponent* C : Camera->GetComponents()) if (C && C->GetFName() == TEXT("Rain")) if (USceneComponent* SC = Cast<USceneComponent>(C)) SC->SetVisibility(!bOn, true);
}

void ABenchGameMode::UpdateDownpour(double T)
{
	// Failing sign: deterministic stutter (function of path time only), sparks burst in the system itself.
	const double f = FMath::Frac(T * 0.43 + 0.37);
	const float On = f < 0.14 ? (FMath::Frac(T * 17.0) < 0.5 ? 0.05f : 1.3f) : (f < 0.2 ? 0.0f : 0.9f + 0.1f * FMath::Sin(T * 40.0));
	if (FailSign) FailSign->SetVectorParameterValue(TEXT("Color"), FailColor * On);
	if (FailLight) FailLight->SetIntensity(FailBase * On);
	// Drones: three pairs, each pair a lead + wingman on a slow figure-eight patrol over the market.
	for (const FDrone& Dr : Drones)
	{
		if (!Dr.Actor) continue;
		const int32 Pair = Dr.Index / 2; const bool bWing = Dr.Index % 2;
		const double Ph = Pair * 2.1 + (bWing ? -0.12 : 0.0), w = 0.11;     // rad/s: one loop per ~57 s
		auto At = [&](double t) { const double a = w * t + Ph; return FVector(900 * FMath::Sin(a * 2) + (bWing ? 180 : 0), 4200 + 3200 * FMath::Sin(a), 1500 + Pair * 220 + 60 * FMath::Sin(t * 0.5 + Pair)); };
		const FVector Pp = At(T), Vel = (At(T + 0.25) - At(T - 0.25)) * 2.0, Acc = (At(T + 0.25) - 2 * Pp + At(T - 0.25)) * 16.0;
		const float Yaw = Vel.Rotation().Yaw;
		const float Bank = FMath::Clamp(float(FVector::CrossProduct(Vel.GetSafeNormal(), Acc).Z) * 0.08f, -18.f, 18.f);
		Dr.Actor->SetActorLocationAndRotation(Pp, FRotator(-4.f, Yaw, Bank));
		if (Dr.Search) Dr.Search->SetRelativeRotation(FRotator(-62.f + 10.f * FMath::Sin(T * 0.7 + Dr.Index), 25.f * FMath::Sin(T * 0.45 + Dr.Index * 1.3), 0));
		const bool bBlink = FMath::Frac(T * 0.9 + Dr.Index * 0.17) < 0.12;
		if (Dr.NavL) Dr.NavL->SetIntensity(bBlink ? 3000.f : 150.f);
		if (Dr.NavR) Dr.NavR->SetIntensity(bBlink ? 150.f : 3000.f);
	}
	if (!Camera) return;
	// Street-level walk north through the market: Catmull-Rom through (x, y, z) keys, 60 s.
	static const double Kt[] = { 0, 9.6, 19.2, 28.8, 38.4, 48, 60 };   // ~22% faster, same 60 s
	static const FVector Kp[] = { {300,300,190}, {-150,1900,175}, {350,3500,175}, {-300,5000,160}, {450,6600,270}, {-350,7650,250}, {-150,9300,240} };
	int32 k = 0; while (k < 5 && T > Kt[k + 1]) ++k;
	const double u = (T - Kt[k]) / (Kt[k + 1] - Kt[k]);
	auto Key = [&](int32 i) { return Kp[FMath::Clamp(i, 0, 6)]; };
	const FVector P0 = Key(k - 1), P1 = Key(k), P2 = Key(k + 1), P3 = Key(k + 2);
	const double u2 = u * u, u3 = u2 * u;
	const FVector Pos = 0.5 * ((2 * P1) + (-P0 + P2) * u + (2 * P0 - 5 * P1 + 4 * P2 - P3) * u2 + (-P0 + 3 * P1 - 3 * P2 + P3) * u3);
	// Look ahead down the market, glance up at the drones mid-run and at the failing sign.
	FVector Look = Pos + FVector(0, 1500, 60);
	Look = FMath::Lerp(Look, FVector(0, 4500, 1600), OmaBench::Smooth((T - 26) / 5) * (1 - OmaBench::Smooth((T - 33) / 5)));
	Look = FMath::Lerp(Look, SparkPos, 0.6 * OmaBench::Smooth((T - 6) / 4) * (1 - OmaBench::Smooth((T - 13) / 4)));
	FRotator R = (Look - Pos).Rotation(); R.Roll = 1.5f * FMath::Sin(T * 0.6);
	Camera->SetActorLocationAndRotation(Pos, R);
	if (RainHost) RainHost->SetActorLocation(FVector(Pos.X, Pos.Y + 800, 0));
	if (APlayerController* PC = GetWorld()->GetFirstPlayerController()) if (PC->GetViewTarget() != Camera) PC->SetViewTarget(Camera);
}
